> >   static atomic_int stop;
> >   static atomic_long opens, creates, enoent, other;
> >   static long period;
> > 
> >   static void die(const char *what)
> >   {
> >   	fprintf(stderr, "FATAL %s: %s\n", what, strerror(errno));
> >   	exit(2);
> >   }
